HEADER_FILL = PatternFill(start_color="1D4ED8",end_color="1D4ED8",fill_type="solid")
HEADER_FONT = Font(bold=True,color="FFFFFF",name="Calibri",size=11)
DATA_FONT   = Font(name="Calibri",size=10)
CENTER      = Alignment(horizontal="center",vertical="center")

def _create_workbook(filename,sheet,headers,rows):
    sheet_name=sheet
    OUTPUT_DIR.mkdir(parents=True,exist_ok=True)
    path = OUTPUT_DIR/filename
    wb = openpyxl.Workbook(); ws = wb.active; ws.title = sheet_name; ws.freeze_panes="A2"
    for ci,h in enumerate(headers,1):
        c=ws.cell(row=1,column=ci,value=h); c.fill=HEADER_FILL; c.font=HEADER_FONT; c.alignment=CENTER
        ws.column_dimensions[get_column_letter(ci)].width=max(len(h)+6,14)
    for ri,row in enumerate(rows,2):
        for ci,v in enumerate(row,1): c=ws.cell(row=ri,column=ci,value=v); c.font=DATA_FONT; c.alignment=CENTER
    wb.save(path); LOGGER.info("[EXCEL] Gerada: %s (%d registros)",path.name,len(rows))

KPI_REPORTS=[
    {"filename":"relatorio_logistic_cost.xlsx","sheet":"logistic_cost","headers":["month","year","target","result","achievement"],"rows":LOGISTIC_COST_DATA},
    {"filename":"relatorio_air_freight.xlsx","sheet":"air_freight","headers":["month","year","target","result","achievement"],"rows":AIR_FREIGHT_DATA},
    {"filename":"relatorio_logistics_vs_prod.xlsx","sheet":"logistics_vs_prod","headers":["month","year","logisticsCost","productionAmount","ratio"],"rows":LOGISTICS_VS_PROD_DATA},
    {"filename":"relatorio_incidental_cost.xlsx","sheet":"incidental_cost","headers":["month","year","target","result","achievement"],"rows":INCIDENTAL_COST_DATA},
    {"filename":"relatorio_total_cost.xlsx","sheet":"total_cost","headers":["month","year","target","result","achievement"],"rows":TOTAL_COST_DATA},
    {"filename":"relatorio_demurrage.xlsx","sheet":"demurrage","headers":["month","year","target","result","achievement"],"rows":DEMURRAGE_DATA},
]

LOGGER.info("[EXCEL] Gerando %d planilhas em: %s", len(KPI_REPORTS), OUTPUT_DIR)
for r in KPI_REPORTS: _create_workbook(**r)
LOGGER.info("[EXCEL] Todas as planilhas geradas com sucesso.")
